#include <iostream>

template<typename T>
void print(T arg) {  // Base case
    std::cout << arg;
}

template<typename T, typename... Args>
void print(T first, Args... args) {  // Recursive case
    std::cout << first << " ";  // Process the first argument
    print(args...);  // Expand the pack recursively
}

int main() {
    print(1, 2.5, "hello", true);  // Calls the variadic function
    return 0;
}
